func webSearchURLToMobileParams(u *url.URL) (map[string]string, []string, error) {
	parts := splitPath(u.Path)
	if len(parts) < 2 || !strings.EqualFold(parts[0], "Suche") {
		return nil, nil, fmt.Errorf("unsupported web path %q", u.Path)
	}
	warnings := []string{}
	params := map[string]string{}
	slug := parts[len(parts)-1]
	realType, ok := webRealEstateSlugToMobile(slug)
	if !ok {
		if warmType, warmPrice, warmOK := warmRentSlug(slug); warmOK {
			realType = warmType
			params["price"] = warmPrice
			params["pricetype"] = "calculatedtotalrent"
		} else {
			warnings = append(warnings, fmt.Sprintf("unknown web real-estate slug %q; defaulting to apartmentrent", slug))
			realType = "apartmentrent"
		}
	}
	params["realestatetype"] = realType
	if extra := webSlugEquipment(slug); extra != "" {
		mergeCommaParam(params, "equipment", extra)
	}

	locationParts := parts[1 : len(parts)-1]
	switch {
	case len(locationParts) == 0:
		params["searchType"] = "region"
	case strings.EqualFold(locationParts[0], "radius"):
		params["searchType"] = "radius"
	case strings.EqualFold(locationParts[0], "shape"):
		params["searchType"] = "shape"
	default:
		params["searchType"] = "region"
		params["geocodes"] = "/" + strings.Join(locationParts, "/")
	}

	query := u.Query()
	copyWebSearchParam(query, params, "geocodes")
	copyWebSearchParam(query, params, "geocoordinates")
	copyWebSearchParam(query, params, "numberofrooms")
	copyWebSearchParam(query, params, "livingspace")
	copyWebSearchParam(query, params, "price")
	copyWebSearchParam(query, params, "pricetype")
	copyWebSearchParam(query, params, "sorting")
	copyWebSearchParam(query, params, "apartmenttypes")
	copyWebSearchParam(query, params, "buildingtypes")
	copyWebSearchParam(query, params, "fulltext")
	copyWebSearchParam(query, params, "constructionyear")
	copyWebSearchParam(query, params, "floor")
	copyWebSearchParam(query, params, "ground")
	copyWebSearchParam(query, params, "newbuilding")
	copyWebSearchParam(query, params, "energyefficiencyclasses")
	copyWebSearchParam(query, params, "heatingtypes")
	copyWebSearchParam(query, params, "petsallowedtypes")
	copyWebSearchParam(query, params, "haspromotion")
	if rawShape := firstValue(query, "shape"); rawShape != "" {
		if decoded, err := decodeWebShape(rawShape); err == nil {
			params["shape"] = decoded
			params["searchType"] = "shape"
		} else {
			params["shape"] = rawShape
			warnings = append(warnings, "shape parameter could not be base64-decoded; kept raw value")
		}
	}
	if equipment := firstValue(query, "equipment"); equipment != "" {
		mergeCommaParam(params, "equipment", mapCommaValues(equipment, webEquipmentToMobile))
	}
	if exclusion := firstValue(query, "exclusioncriteria"); exclusion != "" {
		params["exclusioncriteria"] = mapCommaValues(exclusion, webExclusionToMobile)
	}
	return normalizeSearchParams(params), warnings, nil
}

func mobileSearchURLToParams(u *url.URL) map[string]string {
	path := strings.TrimRight(u.Path, "/")
	if path != "/search/list" && path != "/search/total" && path != "/search/map/v3" {
		return nil
	}
	params := map[string]string{}
	for key, values := range u.Query() {
		if len(values) == 0 || values[0] == "" {
			continue
		}
		params[key] = values[0]
	}
	return normalizeSearchParams(params)
}

